using UnityEngine;

[RequireComponent(typeof(Renderer))]
public class Animation : MonoBehaviour
{
    private Material materiau;

    void Start()
    {
        materiau = GetComponent<Renderer>().material;
        transform.Rotate(0f, 7f * Mathf.Rad2Deg, 0f, Space.Self);
    }

    void Update()
    {
        if (Input.GetKeyDown(KeyCode.A)) ChangerCouleur();
    }

    public void ChangerCouleur()
    {
        if (materiau != null) materiau.color = Color.red;
    }

    void OnDestroy()
    {
        if (materiau != null) Destroy(materiau);
    }
}

